#!/usr/bin/env php
<?php
// Generates the cron-jobs reference fragment for the documentation site.
// Requires cron-jobs.php (stubbing MoreI18N::translate),
// then emits a Markdown fragment with Jobs / Commands / Events tables.
//
// With --lang=<code> (e.g. --lang=de):
//   - structural strings (headings, table headers, values) switch to that language
//   - PO content translations load from util/i18n-<code>.json
//     (generated by: node util/extract-po-json.mjs > util/i18n-de.json)
// Without the flag (or --lang=en): EN structural strings, identity translate().
//
// Output: stdout (fragment, no frontmatter)
// Target: content/{en,de}/includes/linkenhancer/cron-jobs.md (in wt-modules)
//
// Run:
//   php util/generate-cron-jobs-doc.php > .../content/en/includes/linkenhancer/cron-jobs.md
//   php util/generate-cron-jobs-doc.php --lang=de > .../content/de/includes/linkenhancer/cron-jobs.md

declare(strict_types=1);

namespace Schwendinger\Webtrees\Helpers {
    class MoreI18N
    {
        public static function translate(string $text): string
        {
            $map = $GLOBALS['__doc_i18n_map'] ?? [];
            return $map[$text] ?? $text;
        }
    }
}

namespace {

    $lang = 'en';
    foreach (array_slice($argv, 1) as $arg) {
        if (str_starts_with($arg, '--lang=')) {
            $lang = substr($arg, 7);
            break;
        }
    }
    if ($lang !== 'en') {
        $i18nFile = __DIR__ . "/i18n-{$lang}.json";
        if (file_exists($i18nFile)) {
            $GLOBALS['__doc_i18n_map'] = json_decode(
                (string) file_get_contents($i18nFile), true
            ) ?: [];
        }
    }

    // Structural (non-PO) strings. EN is the base; DE overrides only the keys
    // that differ. These live in the script because they are NOT in the PO files.
    $ui = [
        'auto'       => '_Auto-generated by `util/generate-cron-jobs-doc.php` — do not edit manually._',
        'jobs'       => '## Jobs',
        'jobsHead'   => '| Name | Title | Trigger | Command | Args | Timeout (s) | Default |',
        'enabled'    => 'enabled',
        'disabled'   => '**disabled**',
        'default'    => 'default',
        'commands'   => '## Commands',
        'paramsHead' => '| Parameter | Default | Description |',
        'noParams'   => '_(no parameters)_',
        'events'     => '## Events',
        'eventsHead' => '| Name | Description |',
    ];
    if ($lang === 'de') {
        $ui = array_merge($ui, [
            'auto'       => '_Automatisch generiert von `util/generate-cron-jobs-doc.php` — nicht manuell bearbeiten._',
            'jobsHead'   => '| Name | Titel | Trigger | Befehl | Argumente | Timeout (s) | Standard |',
            'enabled'    => 'aktiviert',
            'disabled'   => '**deaktiviert**',
            'default'    => 'Standard',
            'commands'   => '## Befehle',
            'paramsHead' => '| Parameter | Standard | Beschreibung |',
            'noParams'   => '_(keine Parameter)_',
            'eventsHead' => '| Name | Beschreibung |',
        ]);
    }

    $manifestFile = dirname(__DIR__) . '/cron-jobs.php';

    if (!file_exists($manifestFile)) {
        fwrite(STDERR, "ERROR: cron-jobs.php not found at {$manifestFile}\n");
        exit(1);
    }

    $manifest = require $manifestFile;

    $md = $ui['auto'] . "\n\n";

    // --- Jobs ---
    if (!empty($manifest['jobs'])) {
        $md .= $ui['jobs'] . "\n\n";
        $md .= $ui['jobsHead'] . "\n";
        $md .= "| --- | --- | --- | --- | --- | --- | --- |\n";

        foreach ($manifest['jobs'] as $job) {
            $name    = $job['name'];
            $title   = $job['title'];
            $trig    = array_map(
                fn(array $t): string => $t['type'] === 'time'
                    ? "`{$t['cron']}`"
                    : "`{$t['event']}`",
                $job['triggers']
            );
            $trigger = implode('<br>', $trig);
            $cmd     = '`' . basename($job['command']) . '`';
            $args    = $job['args'] ?? '';
            $args    = $args !== '' ? '`' . $args . '`' : '—';
            $timeout = isset($job['timeout_sec']) ? (string) $job['timeout_sec'] : '30 (' . $ui['default'] . ')';
            $enabled = $job['enabled'] ?? true;
            $default = $enabled ? $ui['enabled'] : $ui['disabled'];

            $md .= "| `{$name}` | {$title} | {$trigger} | {$cmd} | {$args} | {$timeout} | {$default} |\n";
        }
        $md .= "\n";
    }

    // --- Commands ---
    if (!empty($manifest['commands'])) {
        $md .= $ui['commands'] . "\n\n";

        foreach ($manifest['commands'] as $cmd) {
            $md .= "### `" . basename($cmd['command']) . "`\n\n";
            $md .= $cmd['description'] . "\n\n";

            if (!empty($cmd['params'])) {
                $md .= $ui['paramsHead'] . "\n";
                $md .= "| --- | --- | --- |\n";
                foreach ($cmd['params'] as $p) {
                    $name    = '`' . $p['name'] . '`';
                    $default = $p['default'] ?? '—';
                    $desc    = $p['description'];
                    $md    .= "| {$name} | {$default} | {$desc} |\n";
                }
            } else {
                $md .= $ui['noParams'] . "\n";
            }
            $md .= "\n";
        }
    }

    // --- Events ---
    if (!empty($manifest['events'])) {
        $md .= $ui['events'] . "\n\n";
        $md .= $ui['eventsHead'] . "\n";
        $md .= "| --- | --- |\n";

        foreach ($manifest['events'] as $evt) {
            $md .= "| `{$evt['name']}` | {$evt['description']} |\n";
        }
        $md .= "\n";
    }

    echo $md;
}
